import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Ex04SqlFragmentInclude {

    // 复刻 <include refid="baseColumns"><property name="alias" value="u"/></include>
    // 未定义的属性按 MyBatis PropertyParser 的语义原样保留 ${xxx}
    static String applyProperties(String fragment, Map<String, String> props) {
        Matcher m = Pattern.compile("\\$\\{([^}]+)\\}").matcher(fragment);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String key = m.group(1);
            String val = props.get(key);
            if (val == null) {
                val = "${" + key + "}";
            }
            m.appendReplacement(sb, Matcher.quoteReplacement(val));
        }
        m.appendTail(sb);
        return sb.toString();
    }

    public static void main(String[] args) {
        // <sql id="baseColumns">${alias}.id, ${alias}.name, ${alias}.age</sql>
        String fragment = "${alias}.id, ${alias}.name, ${alias}.age";

        Map<String, String> withU = new HashMap<String, String>();
        withU.put("alias", "u");
        Map<String, String> withT = new HashMap<String, String>();
        withT.put("alias", "t");

        System.out.println("fragment        : " + fragment);
        System.out.println("include alias=u : " + applyProperties(fragment, withU));
        System.out.println("include alias=t : " + applyProperties(fragment, withT));
        System.out.println("include no prop : " + applyProperties(fragment, new HashMap<String, String>()));

        String full = "SELECT " + applyProperties(fragment, withU)
                + " FROM t_user u WHERE u.id = #{id}";
        System.out.println("rendered SQL    : " + full);

        // 片段复用不改写原文：两次 include 各自独立替换
        System.out.println("fragment intact : " + fragment.equals("${alias}.id, ${alias}.name, ${alias}.age"));
    }
}
